package com.ghunsai.dairy.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;
import java.util.List;

/**
 * Prices are never taken from the client; the server uses the current product price.
 * {@code clientRequestId} (optional, e.g. a UUID generated by the app per bill) makes the call
 * idempotent: retrying after a network failure returns the same bill instead of a duplicate.
 */
public record SaleRequest(
        @NotEmpty(message = "At least one product is required")
        @Size(max = 100, message = "A bill can have at most 100 lines")
        List<@Valid @NotNull SaleItemRequest> items,
        @NotNull @DecimalMin(value = "0.0", message = "Cash cannot be negative")
        @Digits(integer = 10, fraction = 2, message = "Cash allows up to 2 decimals") BigDecimal cashAmount,
        @NotNull @DecimalMin(value = "0.0", message = "UPI amount cannot be negative")
        @Digits(integer = 10, fraction = 2, message = "UPI allows up to 2 decimals") BigDecimal upiAmount,
        @NotNull @DecimalMin(value = "0.0", message = "Udhaar cannot be negative")
        @Digits(integer = 10, fraction = 2, message = "Udhaar allows up to 2 decimals") BigDecimal udhaarAmount,
        Long customerId,
        @Size(max = 64, message = "clientRequestId cannot exceed 64 characters") String clientRequestId) {

    public SaleRequest {
        if (cashAmount == null) {
            cashAmount = BigDecimal.ZERO;
        }
        if (upiAmount == null) {
            upiAmount = BigDecimal.ZERO;
        }
        if (udhaarAmount == null) {
            udhaarAmount = BigDecimal.ZERO;
        }
        if (clientRequestId != null && clientRequestId.isBlank()) {
            clientRequestId = null;
        }
    }
}
